head.script:
scwin.onpageload = function() {

};

scwin.anchor1_onclick = function() {
    anchor1.setToolTip(true,"테스트입니다.")
};


			scwin.fireOver = function(node) {
				if (document.createEventObject) {
					node.fireEvent('onmouseover');
				} else if (document.createEvent) {
					window.evt = document.createEvent('MouseEvents');
					evt.initEvent('mouseover', true, false);
					node.dispatchEvent(evt);
				} else if (typeof node.onmouseover == 'function') {
					node.onmouseover();
				}
			}
			scwin.mouseOverBehaviour = function(id) {
				window.el = WebSquare.wUnit.getDomById(id);
				scwin.fireOver(el);
			}	
			scwin.checkVal = function() {
				return WebSquare.wUnit.getDomById('wq_uuid_0_balloonTip').style.display == 'block';
			}
			scwin.unitTest = function() {
				//Unit
				WebSquare.wUnit.start();
				WebSquare.wUnit.addCommand("pause", "500");
				WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('anchor1').click()");
				WebSquare.wUnit.addCommand("pause", "500");						

				WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('anchor1')");
				WebSquare.wUnit.addCommand("pause", "500");
				WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
				WebSquare.wUnit.addCommand("pause", "500");
				//Run test and stop
				WebSquare.wUnit.run();
				WebSquare.wUnit.stop();
			}
			scwin.unitTest();
